interface IShape { double Area(); }

struct Square : IShape
{
    public double Side;
    public double Area() => Side * Side;
}

var s = new Square { Side = 2 };
s.Area();          // call Square::Area — без коробки
IShape sh = s;     // box: копия s уехала в кучу
sh.Area();         // вызов по коробке через интерфейс

